import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const output = path.resolve(root, "dist");
const marker = path.join(output, ".lozic-static-output");
// Only remove our own generated directory, never an arbitrary path or user-owned dist.
if (path.relative(root, output) !== "dist")
  throw new Error("Unexpected output directory");
if (fs.existsSync(output)) {
  if (!fs.existsSync(marker))
    throw new Error(
      "dist already exists and was not generated by this tool. Choose a different output directory.",
    );
  fs.rmSync(output, { recursive: true, force: true });
}
fs.mkdirSync(output, { recursive: true });
fs.writeFileSync(marker, "Generated by tools/build-static.mjs\n");
for (const name of [
  "index.html",
  ".nojekyll",
  "scripts",
  "styles",
  "assets",
  "music.mp3",
  "lyrics.lrc",
])
  fs.cpSync(path.join(root, name), path.join(output, name), {
    recursive: true,
  });
fs.mkdirSync(path.join(output, "docs"), { recursive: true });
fs.copyFileSync(
  path.join(root, "docs/DEPLOYMENT.md"),
  path.join(output, "docs/DEPLOYMENT.md"),
);
console.log(`Static site ready: ${output}`);
console.log(
  "No server code, database, environment files, or node_modules were copied.",
);
